const x = $input.first().json;
const question = String(x['Interview question'] ?? '').trim();
const role = String(x['Target role'] ?? '').trim();
const draft = String(x['Your draft answer'] ?? '').trim();
if (!question || !role) throw new Error('Question and target role are required.');
if (question.length > 8000 || draft.length > 12000 || role.length > 200) throw new Error('Shorten your input: question max 8000, draft max 12000, role max 200 characters.');
if (!x.spreadsheetId || x.spreadsheetId.includes('REPLACE_')) throw new Error('Configure your spreadsheet ID first.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.recipientEmail) || x.recipientEmail === 'you@example.com') throw new Error('Configure your own recipient email first.');
return [{json:{...x,question,role,draft}}];

const response = $input.first().json;
const choice = response.choices?.[0];
if (!choice || choice.finish_reason !== 'stop') throw new Error('OpenAI response incomplete or refused; inspect the execution before retrying.');
let analysis;
try { analysis = JSON.parse(choice.message.content); } catch { throw new Error('OpenAI did not return valid JSON.'); }
const fields=['topic','difficulty','reference_answer','key_concepts','common_mistakes','follow_up_questions','draft_feedback'];
for (const key of fields) if (typeof analysis[key] !== 'string' || !analysis[key].trim()) throw new Error('Missing analysis field: '+key);
const source = $('Validate study input').first().json;
const safe = value => /^[\s]*[=+@-]/.test(String(value)) ? "'" + value : String(value);
const now = new Date();
const review = new Date(now.getTime()+3*86400000).toISOString().slice(0,10);
const row={created_at:now.toISOString(),question:safe(source.question),target_role:safe(source.role),draft_answer:safe(source.draft),review_on:review,status:'To review'};
for (const key of fields) row[key]=safe(analysis[key]);
const emailBody=['INTERVIEW STUDY GUIDE','Question: '+source.question,'Target role: '+source.role,...fields.map(key=>key.replaceAll('_',' ').toUpperCase()+'\n'+analysis[key]),'Suggested review date: '+review,'AI-generated study material. Verify technical claims.'].join('\n\n');
return [{json:{row,emailBody}}];
